/*
 * t_dec_e2e.c -- DEC05 host end-to-end suite: the real client library (client/dec/n2vcd_dec.c) over
 * a SOCK_SEQPACKET transport, a real dec_testd process (dec_testd.c + daemon/n2vcd_srv.c + the
 * decoder service) and fake_ap.c parsing the stream's SPS through DEC03's n2vld model.
 *
 * Streams are generated by run_tests.sh with ffmpeg and checked there against ffprobe.  The
 * expected geometry literals are DEC03's measured vendor table (320x240 -> stride 320, buf_h 256;
 * 1920x1080 -> 1920, 1088, out 3133440), not this implementation's output.
 */
#define _POSIX_C_SOURCE 200809L
#define _DEFAULT_SOURCE

#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/stat.h>
#include <sys/un.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>

#include "fake_ap.h"
#include "n2vcd_dec.h"

static int checks, fails;

#define CK(c) do { \
	checks++; \
	if (!(c)) { fails++; fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #c); } \
} while (0)

#define CKU(a, b) do { \
	uint32_t ck_a = (uint32_t)(a), ck_b = (uint32_t)(b); \
	checks++; \
	if (ck_a != ck_b) { fails++; fprintf(stderr, "FAIL %s:%d: %s = 0x%08x, want 0x%08x\n", \
	                                       __FILE__, __LINE__, #a, ck_a, ck_b); } \
} while (0)

#define CKI(a, b) do { \
	long long ck_a = (long long)(a), ck_b = (long long)(b); \
	checks++; \
	if (ck_a != ck_b) { fails++; fprintf(stderr, "FAIL %s:%d: %s = %lld, want %lld\n", \
	                                       __FILE__, __LINE__, #a, ck_a, ck_b); } \
} while (0)

/* ------------------------------------------------------------------ socket transport */

#define MAXBUF 64

struct str {
	int fd;
	char sock[200];
	char dir[220];
	uint32_t next;
	struct {
		uint32_t h;
		char path[256];
	} b[MAXBUF];
	unsigned nb;
};

static void
sleep_ms(uint32_t ms)
{
	struct timespec ts = { (time_t)(ms / 1000u), (long)(ms % 1000u) * 1000000L };

	while (nanosleep(&ts, &ts) != 0 && errno == EINTR) { }
}

static int
str_try_connect(struct str *s, const char *path)
{
	struct sockaddr_un a;

	if (strlen(path) >= sizeof(a.sun_path)) {
		return -ENAMETOOLONG;
	}
	s->fd = socket(AF_UNIX, SOCK_SEQPACKET, 0);
	if (s->fd < 0) {
		return -errno;
	}
	memset(&a, 0, sizeof(a));
	a.sun_family = AF_UNIX;
	snprintf(a.sun_path, sizeof(a.sun_path), "%s", path);
	if (connect(s->fd, (struct sockaddr *)&a, sizeof(a)) != 0) {
		int e = -errno;

		close(s->fd);
		s->fd = -1;
		return e;
	}
	snprintf(s->sock, sizeof(s->sock), "%s", path);
	snprintf(s->dir, sizeof(s->dir), "%s.buf", path);
	s->next = 0x4000u;
	return 0;
}

static int
str_connect(struct str *s, const char *path, uint32_t timeout_ms)
{
	uint32_t waited = 0;
	int r;

	memset(s, 0, sizeof(*s));
	s->fd = -1;
	for (;;) {
		r = str_try_connect(s, path);
		if (r == 0) {
			return 0;
		}
		if (waited >= timeout_ms) {
			return r;
		}
		sleep_ms(10);
		waited += 10;
	}
}

static int
str_send(void *ctx, const void *msg, uint32_t bytes)
{
	struct str *s = (struct str *)ctx;
	ssize_t n;

	do {
		n = send(s->fd, msg, bytes, MSG_NOSIGNAL);
	} while (n < 0 && errno == EINTR);
	if (n < 0) {
		return errno == EAGAIN ? -EAGAIN : -errno;
	}
	return n == (ssize_t)bytes ? 0 : -EIO;
}

static int
str_recv(void *ctx, void *msg, uint32_t capacity, uint32_t timeout_ms)
{
	struct str *s = (struct str *)ctx;
	struct pollfd p = { s->fd, POLLIN, 0 };
	int pr = poll(&p, 1, (int)timeout_ms);
	ssize_t n;

	if (pr == 0) {
		return -EAGAIN;
	}
	if (pr < 0) {
		return errno == EINTR ? -EAGAIN : -errno;
	}
	do {
		n = recv(s->fd, msg, capacity, 0);
	} while (n < 0 && errno == EINTR);
	if (n == 0) {
		return -EPIPE;
	}
	if (n < 0) {
		return -errno;
	}
	return (int)n;
}

static int
str_buf_alloc(void *ctx, uint32_t bytes, uint32_t *handle)
{
	struct str *s = (struct str *)ctx;
	char path[256];
	int fd;

	if (bytes == 0u || s->nb >= MAXBUF) {
		return -ENOMEM;
	}
	(void)mkdir(s->dir, 0700);
	*handle = s->next++;
	snprintf(path, sizeof(path), "%s/%u", s->dir, *handle);
	fd = open(path, O_RDWR | O_CREAT | O_TRUNC, 0600);
	if (fd < 0) {
		return -errno;
	}
	if (ftruncate(fd, (off_t)bytes) != 0) {
		int e = -errno;

		close(fd);
		return e;
	}
	close(fd);
	s->b[s->nb].h = *handle;
	snprintf(s->b[s->nb].path, sizeof(s->b[s->nb].path), "%s", path);
	s->nb++;
	return 0;
}

static int
str_buf_rw(void *ctx, uint32_t handle, uint32_t offset, void *data, uint32_t bytes, int write)
{
	struct str *s = (struct str *)ctx;
	int fd;
	ssize_t n = -1;
	int found = 0;

	for (unsigned i = 0; i < s->nb; i++) {
		if (s->b[i].h == handle) {
			fd = open(s->b[i].path, O_RDWR);
			if (fd < 0) {
				return -errno;
			}
			found = 1;
			if (write) {
				n = pwrite(fd, data, bytes, (off_t)offset);
			} else {
				n = pread(fd, data, bytes, (off_t)offset);
			}
			close(fd);
			break;
		}
	}
	if (!found) {
		return -ENOENT;
	}
	return n == (ssize_t)bytes ? 0 : -EIO;
}

static int
str_buf_free(void *ctx, uint32_t handle)
{
	struct str *s = (struct str *)ctx;

	for (unsigned i = 0; i < s->nb; i++) {
		if (s->b[i].h == handle) {
			(void)unlink(s->b[i].path);
			s->b[i] = s->b[s->nb - 1];
			s->nb--;
			return 0;
		}
	}
	return -ENOENT;
}

static void
str_close(void *ctx)
{
	struct str *s = (struct str *)ctx;

	if (s->fd >= 0) {
		close(s->fd);
		s->fd = -1;
	}
	for (unsigned i = 0; i < s->nb; i++) {
		(void)unlink(s->b[i].path);
	}
	s->nb = 0;
	(void)rmdir(s->dir);
}

static struct n2vcd_transport
str_transport(struct str *s)
{
	struct n2vcd_transport t;

	memset(&t, 0, sizeof(t));
	t.ctx = s;
	t.send = str_send;
	t.recv = str_recv;
	t.buf_alloc = str_buf_alloc;
	t.buf_rw = str_buf_rw;
	t.buf_free = str_buf_free;
	t.close = str_close;
	return t;
}

/* ------------------------------------------------------------------ stream helpers */

static uint8_t *
read_file(const char *path, size_t *bytes)
{
	FILE *f = fopen(path, "rb");
	uint8_t *p;
	long n;

	if (!f) {
		return NULL;
	}
	if (fseek(f, 0, SEEK_END) != 0) {
		fclose(f);
		return NULL;
	}
	n = ftell(f);
	if (n <= 0) {
		fclose(f);
		return NULL;
	}
	rewind(f);
	p = (uint8_t *)malloc((size_t)n);
	if (!p || fread(p, 1, (size_t)n, f) != (size_t)n) {
		free(p);
		fclose(f);
		return NULL;
	}
	fclose(f);
	*bytes = (size_t)n;
	return p;
}

static const uint8_t *
next_sc(const uint8_t *p, const uint8_t *e)
{
	for (; p + 3 <= e; p++) {
		if (p[0] == 0 && p[1] == 0 && p[2] == 1) {
			return p;
		}
	}
	return e;
}

/* One Annex B access unit (H.264): the same rule as dec1/vdec_ref.c. */
static size_t
au_len(const uint8_t *b, size_t n)
{
	const uint8_t *e = b + n, *p = next_sc(b, e);
	int seen_vcl = 0;

	while (p < e) {
		const uint8_t *nal = p + 3;
		int t = nal < e ? (nal[0] & 0x1f) : 0;
		const uint8_t *start = (p > b && p[-1] == 0) ? p - 1 : p;
		int vcl = (t == 1 || t == 5);

		if (seen_vcl && ((!vcl && (t == 6 || t == 7 || t == 8 || t == 9 || (t >= 14 && t <= 18))) ||
		                 (vcl && nal + 1 < e && (nal[1] & 0x80)))) {
			return (size_t)(start - b);
		}
		if (vcl) {
			seen_vcl = 1;
		}
		p = next_sc(nal, e);
	}
	return n;
}

struct au {
	const uint8_t *p;
	size_t n;
};

static unsigned
split_aus(const uint8_t *buf, size_t bytes, struct au *out, unsigned max)
{
	unsigned n = 0;
	size_t off = 0;

	while (off < bytes && n < max) {
		size_t len = au_len(buf + off, bytes - off);

		if (len == 0) {
			break;
		}
		out[n].p = buf + off;
		out[n].n = len;
		n++;
		off += len;
	}
	return n;
}

/* ------------------------------------------------------------------ daemon */

static pid_t
spawn_daemon(const char *testd, const char *sock, const char *dir, const char *a1, const char *a2)
{
	pid_t p = fork();

	if (p == 0) {
		if (a1 && a2) {
			execl(testd, testd, "--socket", sock, "--dma-dir", dir, a1, a2, "--quiet", (char *)NULL);
		} else if (a1) {
			execl(testd, testd, "--socket", sock, "--dma-dir", dir, a1, "--quiet", (char *)NULL);
		} else {
			execl(testd, testd, "--socket", sock, "--dma-dir", dir, "--quiet", (char *)NULL);
		}
		_exit(127);
	}
	return p;
}

static int
stop_daemon(pid_t p)
{
	int st = 0;

	if (p <= 0) {
		return -1;
	}
	(void)kill(p, SIGTERM);
	if (waitpid(p, &st, 0) != p) {
		return -1;
	}
	return WIFEXITED(st) ? WEXITSTATUS(st) : -1;
}

/* ------------------------------------------------------------------ tests */

static void
test_stream_320(const char *sock, const char *stream, const struct fake_ap *pattern)
{
	struct str s;
	struct n2vcd_dec_client *cli = NULL;
	struct n2vcd_dec_session *sess = NULL;
	struct n2vcd_dec_geometry geo;
	size_t bytes = 0;
	uint8_t *buf = read_file(stream, &bytes);
	struct au aus[64];
	unsigned n_au = 0;
	uint64_t pts[64];
	unsigned np = 0;

	CK(buf != NULL);
	if (!buf) {
		return;
	}
	n_au = split_aus(buf, bytes, aus, 64);
	CK(n_au >= 4);
	CK(str_connect(&s, sock, 3000) == 0);
	struct n2vcd_transport tr = str_transport(&s);

	CKI(n2vcd_dec_connect(&cli, &tr, 3000, NULL, 0), N2VCD_E_OK);
	CK(cli != NULL);
	if (!cli) {
		free(buf);
		return;
	}
	CKI(n2vcd_dec_open(cli, N2VCD_CODEC_H264, 0, 0, 0, &sess, NULL, NULL, 0), N2VCD_E_OK);
	CK(sess != NULL);
	CKI(n2vcd_dec_header(sess, aus[0].p, (uint32_t)aus[0].n, &geo), N2VCD_E_OK);
	CKU(geo.width, 320);
	CKU(geo.height, 240);
	CKU(geo.stride, 320);
	CKU(geo.buf_h, 256);
	CKU(geo.y_bytes, 81920);
	CKU(geo.c_bytes, 40960);
	CKU(geo.out_buf_bytes, 122880);
	CKU(geo.fourcc, N2VCD_FMT_MM21);
	CKI(n2vcd_dec_add_buffers(sess, &geo), N2VCD_E_OK);

	struct n2vcd_dec_input_info info;
	unsigned inputs = 0;

	for (unsigned i = 1; i < n_au; i++) {
		uint64_t t = 1000u + i;

		CKI(n2vcd_dec_input(sess, aus[i].p, (uint32_t)aus[i].n, t, 0, &info), N2VCD_E_OK);
		CKU(info.changed, 0);
		inputs++;
		struct n2vcd_dec_pic fr;

		for (uint32_t k = 0; k < info.pictures_ready; k++) {
			CKI(n2vcd_dec_picture(sess, &fr), 1);
			CKU(fr.width, 320);
			CKU(fr.height, 240);
			CKU(fr.stride, 320);
			CKU(fr.buf_h, 256);
			CK(fr.y_handle != 0);
			/* The daemon wrote this buffer; the client reads it back from the shared file. */
			CK(fake_ap_check_picture(pattern, fr.y_handle, geo.y_bytes, fr.pts, fr.index + 1u) == 1);
			if (np < 64) {
				pts[np++] = fr.pts;
			}
			CKI(n2vcd_dec_release(sess, fr.index), N2VCD_E_OK);
		}
	}
	uint32_t ready = 0;

	CKI(n2vcd_dec_flush(sess, &ready), N2VCD_E_OK);
	CKI(ready, 2);          /* reorder 2: the last two pictures wait for the flush */
	struct n2vcd_dec_pic fr;

	for (uint32_t i = 0; i < ready; i++) {
		CKI(n2vcd_dec_picture(sess, &fr), 1);
		CK(fake_ap_check_picture(pattern, fr.y_handle, geo.y_bytes, fr.pts, fr.index + 1u) == 1);
		if (np < 64) {
			pts[np++] = fr.pts;
		}
		CKI(n2vcd_dec_release(sess, fr.index), N2VCD_E_OK);
	}
	CKI(n2vcd_dec_picture(sess, &fr), 0);
	CKU(np, inputs);
	for (unsigned i = 0; i < np; i++) {
		CKU(pts[i], 1001u + i);
	}
	CKI(n2vcd_dec_close(sess), N2VCD_E_OK);
	sess = NULL;
	n2vcd_dec_disconnect(cli);
	free(buf);
}

static void
test_stream_1080(const char *sock, const char *stream)
{
	struct str s;
	struct n2vcd_dec_client *cli = NULL;
	struct n2vcd_dec_session *sess = NULL;
	struct n2vcd_dec_geometry geo;
	size_t bytes = 0;
	uint8_t *buf = read_file(stream, &bytes);
	struct au aus[8];
	unsigned n_au;

	CK(buf != NULL);
	if (!buf) {
		return;
	}
	n_au = split_aus(buf, bytes, aus, 8);
	CK(n_au >= 1);
	CK(str_connect(&s, sock, 3000) == 0);
	struct n2vcd_transport tr = str_transport(&s);

	CKI(n2vcd_dec_connect(&cli, &tr, 3000, NULL, 0), N2VCD_E_OK);
	CKI(n2vcd_dec_open(cli, N2VCD_CODEC_H264, 0, 0, 0, &sess, NULL, NULL, 0), N2VCD_E_OK);
	CKI(n2vcd_dec_header(sess, aus[0].p, (uint32_t)aus[0].n, &geo), N2VCD_E_OK);
	CKU(geo.width, 1920);
	CKU(geo.height, 1080);
	CKU(geo.stride, 1920);
	CKU(geo.buf_h, 1088);
	CKU(geo.y_bytes, 2088960);
	CKU(geo.c_bytes, 1044480);
	CKU(geo.out_buf_bytes, 3133440);
	CKI(n2vcd_dec_close(sess), N2VCD_E_OK);
	n2vcd_dec_disconnect(cli);
	free(buf);
}

static void
test_fatal(const char *testd, const char *sock, const char *dir)
{
	pid_t p = spawn_daemon(testd, sock, dir, "--guest-stop", NULL);
	struct str s;
	struct n2vcd_dec_client *cli = NULL;
	int r;

	CK(p > 0);
	CK(str_connect(&s, sock, 3000) == 0);
	struct n2vcd_transport tr = str_transport(&s);

	r = n2vcd_dec_connect(&cli, &tr, 2000, NULL, 0);
	CKI(r, N2VCD_E_GUEST);
	CK(cli == NULL);
	str_close(&s);
	CKI(stop_daemon(p), 70);
}

static void
test_idle(const char *testd, const char *sock, const char *dir, const char *stream)
{
	pid_t p = spawn_daemon(testd, sock, dir, "--idle-ms", "50");
	struct str s;
	struct n2vcd_dec_client *cli = NULL;
	struct n2vcd_dec_session *sess = NULL;
	struct n2vcd_dec_geometry geo;
	struct n2vcd_dec_input_info in;
	size_t bytes = 0;
	uint8_t *buf = read_file(stream, &bytes);
	struct au aus[8];
	unsigned n_au = buf ? split_aus(buf, bytes, aus, 8) : 0;

	CK(buf != NULL && n_au >= 1);
	CK(p > 0);
	CK(str_connect(&s, sock, 3000) == 0);
	struct n2vcd_transport tr = str_transport(&s);

	CKI(n2vcd_dec_connect(&cli, &tr, 2000, NULL, 0), N2VCD_E_OK);
	CKI(n2vcd_dec_open(cli, N2VCD_CODEC_H264, 0, 0, 0, &sess, NULL, NULL, 0), N2VCD_E_OK);
	CKI(n2vcd_dec_header(sess, aus[0].p, (uint32_t)aus[0].n, &geo), N2VCD_E_OK);
	/* The idle timer restarts at the header; the daemon's loop ticks every 100 ms. */
	sleep_ms(400);
	CKI(n2vcd_dec_input(sess, aus[0].p, (uint32_t)aus[0].n, 1, 0, &in), N2VCD_E_SESSION);
	n2vcd_dec_close(sess);
	n2vcd_dec_disconnect(cli);
	free(buf);
	CKI(stop_daemon(p), 0);
}

int
main(int argc, char **argv)
{
	if (argc != 5) {
		fprintf(stderr, "usage: %s <dec_testd> <stream320.h264> <stream1080.h264> <tmpdir>\n", argv[0]);
		return 2;
	}
	const char *testd = argv[1];
	const char *s320 = argv[2];
	const char *s1080 = argv[3];
	const char *tmp = argv[4];
	char sock[200], sock2[200], sock3[200], dir[220];
	struct str probe;
	struct fake_ap_cfg pcfg;

	snprintf(sock, sizeof(sock), "%s/e2e-main.sock", tmp);
	snprintf(dir, sizeof(dir), "%s/e2e-main.sock.buf", tmp);
	(void)mkdir(tmp, 0700);
	memset(&pcfg, 0, sizeof(pcfg));
	pcfg.dma_dir = dir;
	pcfg.marker = 0x5a;
	struct fake_ap *pattern = fake_ap_create(&pcfg);

	CK(pattern != NULL);
	pid_t d = spawn_daemon(testd, sock, dir, "--reorder", "2");

	CK(d > 0);
	CK(str_connect(&probe, sock, 3000) == 0);
	str_close(&probe);
	test_stream_320(sock, s320, pattern);
	test_stream_1080(sock, s1080);

	/* Daemon gone while a session is open: the next request is E_SESSION. */
	struct str s;
	struct n2vcd_dec_client *cli = NULL;
	struct n2vcd_dec_session *sess = NULL;
	struct n2vcd_dec_geometry geo;
	struct n2vcd_dec_input_info in;
	size_t bytes = 0;
	uint8_t *buf = read_file(s320, &bytes);
	struct au aus[8];
	unsigned n_au = buf ? split_aus(buf, bytes, aus, 8) : 0;

	CK(buf != NULL && n_au >= 1);
	CK(str_connect(&s, sock, 3000) == 0);
	struct n2vcd_transport tr = str_transport(&s);

	CKI(n2vcd_dec_connect(&cli, &tr, 2000, NULL, 0), N2VCD_E_OK);
	CKI(n2vcd_dec_open(cli, N2VCD_CODEC_H264, 0, 0, 0, &sess, NULL, NULL, 0), N2VCD_E_OK);
	CKI(n2vcd_dec_header(sess, aus[0].p, (uint32_t)aus[0].n, &geo), N2VCD_E_OK);
	CKI(stop_daemon(d), 0);
	CKI(n2vcd_dec_input(sess, aus[0].p, (uint32_t)aus[0].n, 1, 0, &in), N2VCD_E_SESSION);
	n2vcd_dec_close(sess);
	n2vcd_dec_disconnect(cli);
	free(buf);

	snprintf(sock2, sizeof(sock2), "%s/e2e-fatal.sock", tmp);
	snprintf(dir, sizeof(dir), "%s/e2e-fatal.sock.buf", tmp);
	test_fatal(testd, sock2, dir);
	snprintf(sock3, sizeof(sock3), "%s/e2e-idle.sock", tmp);
	snprintf(dir, sizeof(dir), "%s/e2e-idle.sock.buf", tmp);
	test_idle(testd, sock3, dir, s320);

	fake_ap_destroy(pattern);
	if (fails == 0) {
		printf("DEC05 e2e PASS %d/%d\n", checks, checks);
		return 0;
	}
	printf("DEC05 e2e FAIL %d/%d\n", checks - fails, checks);
	return 1;
}
